{
  "title": "log-iscoroutinefunction-call",
  "request": "Can you add a debug log inside iscoroutinefunction so we can see when it's called? I'd like it to log the object being checked.",
  "edits": [
    {
      "path": "src/mcp/shared/_compat.py",
      "search": "return asyncio.iscoroutinefunction(obj)",
      "replace": "    logging.debug(\"iscoroutinefunction called for %s\", obj)\n    return asyncio.iscoroutinefunction(obj)"
    }
  ],
  "test_path": "tests/test_iscoroutinefunction_logging.py",
  "test": "import logging\nimport mcp.shared._compat as compat\n\ndef test_iscoroutinefunction_logs(caplog):\n    caplog.set_level(logging.DEBUG)\n    # Call the function with a simple lambda\n    compat.iscoroutinefunction(lambda: None)\n    # Verify that a debug log was emitted containing our message\n    assert any(\"iscoroutinefunction called\" in record.getMessage() for record in caplog.records)\n"
}
